-- Winter 5787: Hafrashas Challah Part 1 PUBLIC quick review library.
-- Generated by scripts/prepare_winter_review_import.py; __ROW_COUNT__ questions.
-- Run the entire file in Supabase SQL Editor after learning-program migrations.
-- No schema changes, deletions, notifications, or chaburah publication.
-- Re-run updates this bank's stable IDs; unrelated questions/copies/scores stay untouched.
begin;
select pg_advisory_xact_lock(hashtext('myscp:winter-5787:challah-part1:quick-review'));

do $requirements$
begin
  if not exists (select 1 from public.learning_programs where id = 'winter-5787') then
    raise exception 'Winter 5787 is not configured. Apply learning-program migration first.';
  end if;
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'review_questions'
      and column_name = 'is_model_question'
  ) then
    raise exception 'Model-question migration is missing.';
  end if;
end;
$requirements$;

create temp table winter_challah_review_bank (
  id uuid primary key, week smallint not null check (week between 1 and 4),
  topic text not null, prompt text not null, kind public.review_question_kind not null,
  choices jsonb not null, correct_choice_index smallint not null,
  explanation text not null, is_model_question boolean not null,
  check (jsonb_typeof(choices) = 'array'),
  check ((kind = 'true_false' and choices = '["True","False"]'::jsonb)
      or (kind = 'multiple_choice' and jsonb_array_length(choices) = 4)),
  check (correct_choice_index >= 0 and correct_choice_index < jsonb_array_length(choices))
) on commit drop;

insert into winter_challah_review_bank
select id, week, topic, prompt, kind, choices, correct_choice_index, explanation, is_model_question
from jsonb_to_recordset($winter_bank$__BANK_JSON__$winter_bank$::jsonb) as bank (
  id uuid, week smallint, topic text, prompt text, kind public.review_question_kind,
  choices jsonb, correct_choice_index smallint, explanation text, is_model_question boolean
);

do $import$
declare
  author_id uuid;
  imported_count integer;
begin
  select id into author_id from public.profiles where role = 'global_admin' order by id limit 1;
  if author_id is null then
    raise exception 'A Global Admin profile is required before importing.';
  end if;
  if exists (
    select 1 from public.review_questions question join winter_challah_review_bank bank using (id)
    where question.program_id is distinct from 'winter-5787'
      or question.chaburah_id is not null
      or question.visibility is distinct from 'everyone'::public.content_visibility
      or question.is_library_question is distinct from true
      or question.source_question_id is not null
      or question.topic is distinct from bank.topic
  ) then
    raise exception 'Import ID conflicts with an unrelated question. Nothing imported.';
  end if;
  if exists (
    select 1 from public.review_questions question join winter_challah_review_bank bank
      on lower(btrim(question.prompt)) = lower(btrim(bank.prompt)) and question.id <> bank.id
    where question.program_id = 'winter-5787' and question.is_library_question
      and question.visibility = 'everyone' and question.chaburah_id is null
  ) then
    raise exception 'Matching Winter library prompt already exists under another ID. Resolve it before importing.';
  end if;

  insert into public.review_questions as question (
    id, program_id, chaburah_id, topic, week, prompt, kind, choices,
    visibility, enabled, created_by, publication_status, source_question_id,
    is_library_question, published_at, is_model_question
  )
  select id, 'winter-5787', null, topic, week, prompt, kind, choices,
    'everyone'::public.content_visibility, true, author_id, 'published', null,
    true, now(), is_model_question
  from winter_challah_review_bank
  on conflict (id) do update set
    topic = excluded.topic, week = excluded.week, prompt = excluded.prompt,
    kind = excluded.kind, choices = excluded.choices, enabled = true,
    publication_status = 'published', is_model_question = excluded.is_model_question,
    published_at = coalesce(question.published_at, excluded.published_at), updated_at = now()
  where question.program_id = 'winter-5787' and question.chaburah_id is null
    and question.visibility = 'everyone' and question.is_library_question
    and question.source_question_id is null and question.topic = excluded.topic;
  get diagnostics imported_count = row_count;
  if imported_count <> __ROW_COUNT__ then
    raise exception 'Expected __ROW_COUNT__ questions, imported %. Transaction rolled back.', imported_count;
  end if;

  insert into public.review_question_answers (question_id, correct_choice_index, explanation)
  select id, correct_choice_index, explanation from winter_challah_review_bank
  on conflict (question_id) do update set
    correct_choice_index = excluded.correct_choice_index,
    explanation = excluded.explanation, updated_at = now();

  raise notice 'Imported % Winter public-library questions. No chaburah questions published.', imported_count;
end;
$import$;

select bank.week, count(*) as imported_questions,
  count(*) filter (where question.is_model_question) as model_questions,
  count(*) filter (where not question.is_model_question) as extra_questions
from winter_challah_review_bank bank
join public.review_questions question using (id)
group by bank.week order by bank.week;
commit;
